export interface PageFrontmatter {
  title: string;
  date: string;
  tags: string[];
}

export interface Page extends PageFrontmatter {
  slug: string;
  sourcePath: string;
  outputPath: string;
  html: string;
}

export interface BuildOptions {
  contentDir: string;
  outputDir: string;
}

export interface BuildResult {
  pages: Page[];
  outputDir: string;
}

import * as fs from 'fs';
import * as path from 'path';
import matter from 'gray-matter';
import { marked } from 'marked';
import { Page } from './types';

export function slugify(fileName: string): string {
  const base = fileName.replace(/\.md$/i, '');
  return base
    .toLowerCase()
    .trim()
    .replace(/[^a-z0-9]+/g, '-')
    .replace(/^-+|-+$/g, '');
}

export function titleFromSlug(slug: string): string {
  return slug
    .split('-')
    .filter(Boolean)
    .map((word) => word[0].toUpperCase() + word.slice(1))
    .join(' ');
}

export function normalizeTags(tags: unknown): string[] {
  if (Array.isArray(tags)) {
    return tags.map((tag) => String(tag).trim()).filter(Boolean);
  }
  if (typeof tags === 'string') {
    return tags
      .split(',')
      .map((tag) => tag.trim())
      .filter(Boolean);
  }
  return [];
}

export function parseMarkdownFile(filePath: string, contentDir: string): Page {
  const raw = fs.readFileSync(filePath, 'utf-8');
  const { data, content } = matter(raw);

  const relativePath = path.relative(contentDir, filePath);
  const fileName = path.basename(filePath);
  const slug = slugify(relativePath.replace(/\\/g, '/'));

  const title = typeof data.title === 'string' && data.title.trim() ? data.title.trim() : titleFromSlug(slugify(fileName));
  const date = typeof data.date === 'string' ? data.date : data.date ? String(data.date) : '';
  const tags = normalizeTags(data.tags);

  const html = marked.parse(content, { async: false }) as string;

  return {
    title,
    date,
    tags,
    slug,
    sourcePath: filePath,
    outputPath: `${slug}.html`,
    html,
  };
}

export function findMarkdownFiles(dir: string): string[] {
  if (!fs.existsSync(dir)) {
    return [];
  }
  const entries = fs.readdirSync(dir, { withFileTypes: true });
  const files: string[] = [];
  for (const entry of entries) {
    const fullPath = path.join(dir, entry.name);
    if (entry.isDirectory()) {
      files.push(...findMarkdownFiles(fullPath));
    } else if (entry.isFile() && /\.md$/i.test(entry.name)) {
      files.push(fullPath);
    }
  }
  return files.sort();
}

import { Page } from './types';

export function escapeHtml(value: string): string {
  return value
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&#39;');
}

function layout(title: string, body: string): string {
  return `<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>${escapeHtml(title)}</title>
</head>
<body>
${body}
</body>
</html>
`;
}

export function renderPage(page: Page): string {
  const tags = page.tags.length
    ? `<ul class="tags">${page.tags.map((tag) => `<li>${escapeHtml(tag)}</li>`).join('')}</ul>`
    : '';
  const date = page.date ? `<p class="date">${escapeHtml(page.date)}</p>` : '';
  const body = `<article>
<h1>${escapeHtml(page.title)}</h1>
${date}
${tags}
<div class="content">
${page.html}
</div>
<p><a href="index.html">&larr; Back to index</a></p>
</article>`;
  return layout(page.title, body);
}

export function renderIndex(pages: Page[]): string {
  const sorted = [...pages].sort((a, b) => (b.date || '').localeCompare(a.date || ''));
  const items = sorted
    .map((page) => {
      const date = page.date ? ` <span class="date">${escapeHtml(page.date)}</span>` : '';
      return `<li><a href="${escapeHtml(page.outputPath)}">${escapeHtml(page.title)}</a>${date}</li>`;
    })
    .join('\n');
  const body = `<h1>Site Index</h1>
<ul class="pages">
${items}
</ul>`;
  return layout('Site Index', body);
}

import * as fs from 'fs';
import * as path from 'path';
import { findMarkdownFiles, parseMarkdownFile } from './parser';
import { renderIndex, renderPage } from './templates';
import { BuildOptions, BuildResult } from './types';

export function build(options: BuildOptions): BuildResult {
  const contentDir = path.resolve(options.contentDir);
  const outputDir = path.resolve(options.outputDir);

  if (!fs.existsSync(contentDir)) {
    throw new Error(`Content directory not found: ${contentDir}`);
  }

  const files = findMarkdownFiles(contentDir);
  const pages = files.map((file) => parseMarkdownFile(file, contentDir));

  const slugCounts = new Map<string, number>();
  for (const page of pages) {
    slugCounts.set(page.slug, (slugCounts.get(page.slug) || 0) + 1);
  }
  const duplicates = [...slugCounts.entries()].filter(([, count]) => count > 1);
  if (duplicates.length > 0) {
    const names = duplicates.map(([slug]) => slug).join(', ');
    throw new Error(`Duplicate page slug(s) detected: ${names}`);
  }

  fs.mkdirSync(outputDir, { recursive: true });

  for (const page of pages) {
    const outFile = path.join(outputDir, page.outputPath);
    fs.mkdirSync(path.dirname(outFile), { recursive: true });
    fs.writeFileSync(outFile, renderPage(page), 'utf-8');
  }

  fs.writeFileSync(path.join(outputDir, 'index.html'), renderIndex(pages), 'utf-8');

  return { pages, outputDir };
}

#!/usr/bin/env node
import { Command } from 'commander';
import { build } from './build';

export function createProgram(): Command {
  const program = new Command();

  program.name('ssg').description('A static site generator').version('1.0.0');

  program
    .command('build')
    .description('Generate the site from Markdown content')
    .option('--content <dir>', 'content directory', './content')
    .option('--output <dir>', 'output directory', './dist')
    .action((opts: { content: string; output: string }) => {
      const result = build({ contentDir: opts.content, outputDir: opts.output });
      console.log(`Built ${result.pages.length} page(s) into ${result.outputDir}`);
    });

  return program;
}

if (require.main === module) {
  createProgram().parse(process.argv);
}

export * from './types';
