import * as fs from 'fs';
import * as os from 'os';
import * as path from 'path';
import {
  findMarkdownFiles,
  normalizeTags,
  parseMarkdownFile,
  slugify,
  titleFromSlug,
} from '../src/parser';

function makeTempDir(): string {
  return fs.mkdtempSync(path.join(os.tmpdir(), 'ssg-parser-'));
}

describe('slugify', () => {
  it('lowercases and hyphenates', () => {
    expect(slugify('Hello World.md')).toBe('hello-world');
  });

  it('strips non-alphanumeric characters', () => {
    expect(slugify('My Post! #1.md')).toBe('my-post-1');
  });

  it('handles nested paths', () => {
    expect(slugify('blog/My Post.md')).toBe('blog-my-post');
  });
});

describe('titleFromSlug', () => {
  it('capitalizes each word', () => {
    expect(titleFromSlug('hello-world')).toBe('Hello World');
  });
});

describe('normalizeTags', () => {
  it('returns array input as trimmed strings', () => {
    expect(normalizeTags(['a', ' b ', 'c'])).toEqual(['a', 'b', 'c']);
  });

  it('splits comma separated strings', () => {
    expect(normalizeTags('a, b,c')).toEqual(['a', 'b', 'c']);
  });

  it('returns empty array for undefined', () => {
    expect(normalizeTags(undefined)).toEqual([]);
  });

  it('filters out empty entries', () => {
    expect(normalizeTags(['a', '', '  '])).toEqual(['a']);
  });
});

describe('parseMarkdownFile', () => {
  let dir: string;

  beforeEach(() => {
    dir = makeTempDir();
  });

  afterEach(() => {
    fs.rmSync(dir, { recursive: true, force: true });
  });

  it('parses frontmatter and converts markdown to html', () => {
    const filePath = path.join(dir, 'my-post.md');
    fs.writeFileSync(
      filePath,
      `---\ntitle: My Post\ndate: 2026-01-01\ntags: [a, b]\n---\n\n# Heading\n\nSome **bold** text.\n`
    );

    const page = parseMarkdownFile(filePath, dir);

    expect(page.title).toBe('My Post');
    expect(page.date).toBe('2026-01-01');
    expect(page.tags).toEqual(['a', 'b']);
    expect(page.slug).toBe('my-post');
    expect(page.outputPath).toBe('my-post.html');
    expect(page.html).toContain('<h1>Heading</h1>');
    expect(page.html).toContain('<strong>bold</strong>');
  });

  it('falls back to a title derived from the filename when missing', () => {
    const filePath = path.join(dir, 'no-frontmatter-title.md');
    fs.writeFileSync(filePath, `---\ndate: 2026-01-01\n---\n\nBody text.\n`);

    const page = parseMarkdownFile(filePath, dir);

    expect(page.title).toBe('No Frontmatter Title');
    expect(page.tags).toEqual([]);
  });

  it('defaults date and tags when entirely absent', () => {
    const filePath = path.join(dir, 'bare.md');
    fs.writeFileSync(filePath, 'Just content, no frontmatter.\n');

    const page = parseMarkdownFile(filePath, dir);

    expect(page.date).toBe('');
    expect(page.tags).toEqual([]);
    expect(page.title).toBe('Bare');
  });
});

describe('findMarkdownFiles', () => {
  let dir: string;

  beforeEach(() => {
    dir = makeTempDir();
  });

  afterEach(() => {
    fs.rmSync(dir, { recursive: true, force: true });
  });

  it('returns an empty array when the directory does not exist', () => {
    expect(findMarkdownFiles(path.join(dir, 'missing'))).toEqual([]);
  });

  it('finds markdown files recursively and ignores other extensions', () => {
    fs.writeFileSync(path.join(dir, 'a.md'), '# A');
    fs.writeFileSync(path.join(dir, 'notes.txt'), 'ignore me');
    fs.mkdirSync(path.join(dir, 'sub'));
    fs.writeFileSync(path.join(dir, 'sub', 'b.md'), '# B');

    const files = findMarkdownFiles(dir).map((f) => path.relative(dir, f));

    expect(files.sort()).toEqual(['a.md', path.join('sub', 'b.md')].sort());
  });
});

import { escapeHtml, renderIndex, renderPage } from '../src/templates';
import { Page } from '../src/types';

function makePage(overrides: Partial<Page> = {}): Page {
  return {
    title: 'Sample Page',
    date: '2026-01-01',
    tags: ['a', 'b'],
    slug: 'sample-page',
    sourcePath: '/content/sample-page.md',
    outputPath: 'sample-page.html',
    html: '<p>Body</p>',
    ...overrides,
  };
}

describe('escapeHtml', () => {
  it('escapes html special characters', () => {
    expect(escapeHtml('<script>alert("x")</script>')).toBe(
      '&lt;script&gt;alert(&quot;x&quot;)&lt;/script&gt;'
    );
  });
});

describe('renderPage', () => {
  it('includes the title, date, tags, and content', () => {
    const html = renderPage(makePage());

    expect(html).toContain('<title>Sample Page</title>');
    expect(html).toContain('<h1>Sample Page</h1>');
    expect(html).toContain('2026-01-01');
    expect(html).toContain('<li>a</li>');
    expect(html).toContain('<li>b</li>');
    expect(html).toContain('<p>Body</p>');
    expect(html).toContain('href="index.html"');
  });

  it('escapes untrusted title content', () => {
    const html = renderPage(makePage({ title: '<img src=x onerror=alert(1)>' }));
    expect(html).not.toContain('<img src=x onerror=alert(1)>');
    expect(html).toContain('&lt;img src=x onerror=alert(1)&gt;');
  });

  it('omits the tag list when there are no tags', () => {
    const html = renderPage(makePage({ tags: [] }));
    expect(html).not.toContain('class="tags"');
  });
});

describe('renderIndex', () => {
  it('lists every page sorted by date descending', () => {
    const pages = [
      makePage({ title: 'Older', date: '2026-01-01', outputPath: 'older.html' }),
      makePage({ title: 'Newer', date: '2026-03-01', outputPath: 'newer.html' }),
    ];

    const html = renderIndex(pages);
    const newerIndex = html.indexOf('Newer');
    const olderIndex = html.indexOf('Older');

    expect(newerIndex).toBeGreaterThan(-1);
    expect(olderIndex).toBeGreaterThan(-1);
    expect(newerIndex).toBeLessThan(olderIndex);
    expect(html).toContain('href="newer.html"');
    expect(html).toContain('href="older.html"');
  });

  it('renders an empty list when there are no pages', () => {
    const html = renderIndex([]);
    expect(html).toContain('<ul class="pages">');
  });
});

import * as fs from 'fs';
import * as os from 'os';
import * as path from 'path';
import { build } from '../src/build';

function makeTempDir(): string {
  return fs.mkdtempSync(path.join(os.tmpdir(), 'ssg-build-'));
}

describe('build', () => {
  let root: string;
  let contentDir: string;
  let outputDir: string;

  beforeEach(() => {
    root = makeTempDir();
    contentDir = path.join(root, 'content');
    outputDir = path.join(root, 'dist');
    fs.mkdirSync(contentDir);
  });

  afterEach(() => {
    fs.rmSync(root, { recursive: true, force: true });
  });

  it('generates an html file per markdown page plus an index', () => {
    fs.writeFileSync(
      path.join(contentDir, 'first.md'),
      '---\ntitle: First\ndate: 2026-01-01\n---\n\nFirst body.\n'
    );
    fs.writeFileSync(
      path.join(contentDir, 'second.md'),
      '---\ntitle: Second\ndate: 2026-02-01\n---\n\nSecond body.\n'
    );

    const result = build({ contentDir, outputDir });

    expect(result.pages).toHaveLength(2);
    expect(fs.existsSync(path.join(outputDir, 'index.html'))).toBe(true);
    expect(fs.existsSync(path.join(outputDir, 'first.html'))).toBe(true);
    expect(fs.existsSync(path.join(outputDir, 'second.html'))).toBe(true);

    const indexHtml = fs.readFileSync(path.join(outputDir, 'index.html'), 'utf-8');
    expect(indexHtml).toContain('href="first.html"');
    expect(indexHtml).toContain('href="second.html"');

    const firstHtml = fs.readFileSync(path.join(outputDir, 'first.html'), 'utf-8');
    expect(firstHtml).toContain('First body.');
  });

  it('creates the output directory if it does not exist', () => {
    fs.writeFileSync(path.join(contentDir, 'only.md'), '# Only page');

    expect(fs.existsSync(outputDir)).toBe(false);
    build({ contentDir, outputDir });
    expect(fs.existsSync(outputDir)).toBe(true);
  });

  it('produces an empty index when there is no markdown content', () => {
    const result = build({ contentDir, outputDir });
    expect(result.pages).toHaveLength(0);
    expect(fs.existsSync(path.join(outputDir, 'index.html'))).toBe(true);
  });

  it('throws when the content directory does not exist', () => {
    expect(() => build({ contentDir: path.join(root, 'missing'), outputDir })).toThrow(
      /Content directory not found/
    );
  });

  it('throws when two pages resolve to the same slug', () => {
    fs.mkdirSync(path.join(contentDir, 'sub'));
    fs.writeFileSync(path.join(contentDir, 'post.md'), '# One');
    fs.writeFileSync(path.join(contentDir, 'sub', 'post.md'), '# Two');

    expect(() => build({ contentDir, outputDir })).toThrow(/Duplicate page slug/);
  });
});

